	if err != nil {
		return nil, fmt.Errorf("merge: %w", err)
	}
	return resp, nil
}

// RepoRevert reverts commit_sha on target_ref. Conflicts are signalled via
// RevertResponse.outcome = CONFLICT, not as an RPC error.
func (c *Client) RepoRevert(ctx context.Context, req *repopb.RevertRequest) (*repopb.RevertResponse, error) {
