// tree sees credentials from the cli's own `entire login` store via the
// existing ENTIRE_TOKEN escape hatch. See bridgeEntireDBAuth for the
// rationale.
func newRepoCmd() *cobra.Command {
	bridgeEntireDBAuth()

	cfg, err := entiredbcli.LoadConfig()
	if err != nil {
		// Mirror the lazy-error pattern used by other top-level commands:
		// surface the config-load failure when the user actually invokes
		// `entire repo …`, not at root construction time.
		return &cobra.Command{
			Use:    "repo",
			Short:  "Read and rewrite repositories on EntireDB clusters",
			Hidden: true,
			RunE: func(cmd *cobra.Command, _ []string) error {
				cmd.SilenceUsage = true
				return NewSilentError(fmt.Errorf("entire repo: load config: %w", err))
			},
		}
	}

	cmd := entiredbcli.NewRepoCmd(cfg)
	cmd.Hidden = true
	entiredbcli.RebrandExamples(cmd, "entire ")
	return cmd
}

// bridgeEntireDBAuth lets `entire repo` reuse credentials that `entire
// login` already wrote, without duplicating tokens across two keyring
// services or rewriting either auth flow. The vendored tree treats
// ENTIRE_TOKEN as a credential override that short-circuits its own
// contexts.json + keyring lookup (see internal/entiredb/cli/creds.go's
// getTokenForHost). We plumb the cli's stored bearer through that
// escape hatch.
//
// We also seed ENTIRE_BASE_URL (the cluster the gRPC dial targets) and
// ENTIRE_CORE_BASE_URL (the JWT issuer + STS host that clone exchanges
// against) from the cli's own base-URL helpers, since the vendored
// Config reads both from env. Real overrides win — when any of these
// env vars is already set we leave them alone, preserving the
// CI / ENTIRE_TOKEN-injection and split-host workflows the upstream
// code documents.
//
// Trade-off: the bridge does not capture refresh tokens — `entire
// login` only issues a bare access token, so the vendored auto-refresh
// path will log a warning and fall back to the existing token when it
// expires. This matches the cli's pre-existing auth UX; refresh-token
// support is a follow-up.
func bridgeEntireDBAuth() {
	if os.Getenv("ENTIRE_TOKEN") != "" {
		// An explicit token override (CI, ops, debugging) wins over the
		// keyring; do not paper over it with a logged-in user's bearer.
		return
	}
	token, err := auth.LookupCurrentToken()
	if err != nil || token == "" {
		// No login on this machine yet. Leave env empty so the vendored
		// resolver runs its own contexts.json path and surfaces the
		// "no logged-in context" error pointing at `entire login`.
		return
	}
	os.Setenv("ENTIRE_TOKEN", token)
	if os.Getenv("ENTIRE_BASE_URL") == "" {
		os.Setenv("ENTIRE_BASE_URL", api.BaseURL())
	}
	if os.Getenv("ENTIRE_CORE_BASE_URL") == "" {
		// validateReceivedToken (login.go) verified iss == AuthBaseURL()
		// at login time, so AuthBaseURL is the right STS host for any
		// repo-scoped token exchange the clone path issues.
		os.Setenv("ENTIRE_CORE_BASE_URL", api.AuthBaseURL())
	}
}

