	if f, err := contexts.Load(cfg.ConfigDir); err == nil {
		if c := f.Resolve(cfg.CredentialHost()); c != nil && c.CoreURL != "" {
			return strings.TrimRight(c.CoreURL, "/")
		}
	}
	return strings.TrimRight(cfg.EntireCoreBaseURL, "/")
