	client := newRepoClient(baseURL, token, nil, opts...)
	return clientConnFunc(client)
}

func ConnectRepoWithRefresh(baseURL string, cfg AuthRefreshConfig, clientConnFunc ConnFunc, opts ...RepoOption) error {
