// newAuthLoginCmd implements both login modes against entire-core. With
// no flags the command runs the interactive loopback OAuth + PKCE flow
// (browser-based, suitable for laptops). With --workload-identity it
// presents an external OIDC token (e.g. a GitHub Actions ID token) and
// the target service account; entire-core's STS exchanges the OIDC
// token for an SA-session JWT bound to that account. Both modes store
// the resulting JWT via the shared tokenstore so subsequent CLI
// commands pick it up automatically.
func newAuthLoginCmd(cfg Config) *cobra.Command {
	var (
		workloadIdentity bool
		token            string
		account          string
		contextName      string
	)
	cmd := &cobra.Command{
		Use:   "login",
		Short: "Log in to entire-core",
		Long: "Default mode is the loopback OAuth + PKCE flow: opens a " +
			"browser to <core>/cli/login, listens on a random 127.0.0.1 " +
			"port for the auth-code callback, redeems the code at " +
			"/api/auth/token, and stores the resulting JWT (and refresh " +
			"token, if issued) under the entire-core URL.\n\n" +
			"The target core URL must be supplied explicitly via --base-url " +
			"or ENTIRE_CORE_AUTH_BASE_URL; login does not fall back to the " +
			"current context, because it is the command that creates one. " +
			"With neither set, login fails with a clear error rather than " +
			"silently hitting localhost.\n\n" +
			"A successful login writes a kubectl-style context to " +
			"~/.config/entire/contexts.json and flips current_context to " +
			"it — shared with entiredb, so a single login covers both " +
			"CLIs. The context name defaults to " +
			"<provider>:<handle>@<host> (e.g. " +
			"github:toothbrush@eu.auth.partial.to), or just the issuer " +
			"host if the server didn't return provider/handle. Pass " +
			"--name to override. See `entire-core context list`.\n\n" +
			"With --workload-identity, presents an OIDC token from a " +
			"registered provider (e.g. GitHub Actions) and the target " +
			"service account; entire-core's STS exchanges it for an " +
			"sa_session JWT bound to that account. Pass --token=- to read " +
			"the OIDC JWT from stdin instead of the command line so it " +
			"doesn't end up in shell history.",
		Example: "  # Interactive login against an explicit core instance\n" +
			"  entire-core --base-url https://core.example auth login\n\n" +
			"  # Equivalent via env var\n" +
			"  ENTIRE_CORE_AUTH_BASE_URL=https://core.example entire-core auth login\n\n" +
			"  # Two handles against the same core (disambiguate with --name)\n" +
			"  entire-core --base-url https://core.example auth login --name eu-paul\n" +
			"  entire-core --base-url https://core.example auth login --name eu-admin\n\n" +
			"  # Inside a GitHub Actions workflow with id-token: write\n" +
			"  OIDC_TOKEN=$(curl -sLS \\\n" +
			"      \"$ACTIONS_ID_TOKEN_REQUEST_URL&audience=https://core.example/api/authz/sts\" \\\n" +
			"      -H \"Authorization: Bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN\" | jq -r '.value')\n" +
			"  entire-core --base-url https://core.example auth login --workload-identity \\\n" +
			"      --token=\"$OIDC_TOKEN\" --account=svc_01HABCDEF...\n\n" +
			"  # Read OIDC token from stdin (keeps it out of shell history)\n" +
			"  echo \"$OIDC_TOKEN\" | entire-core --base-url https://core.example auth login \\\n" +
			"      --workload-identity --token=- --account=svc_01HABCDEF...",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if workloadIdentity {
				if contextName != "" {
					return errors.New("--name does not apply to --workload-identity logins")
				}
				return runWorkloadIdentityLogin(cmd, cfg, token, account)
			}
			if token != "" || account != "" {
				return errors.New("--token and --account require --workload-identity")
			}
			return runInteractiveLogin(cmd, cfg, contextName)
		},
	}
	cmd.Flags().BoolVar(&workloadIdentity, "workload-identity", false, "Exchange an external OIDC token for an SA-session JWT (CI / non-interactive)")
	cmd.Flags().StringVar(&token, "token", "", "OIDC JWT issued by a registered provider (workload-identity mode; pass '-' to read from stdin)")
	cmd.Flags().StringVar(&account, "account", "", "Target service-account ID (workload-identity mode, e.g. svc_<ulid>)")
	cmd.Flags().StringVar(&contextName, "name", "", "Context name to record in contexts.json (default: <provider>:<handle>@<host>)")

	// Read --token from stdin when set to "-", same convention curl,
	// jq etc. use. Saves operators from putting an OIDC JWT on the
	// command line where it'd land in shell history.
	cmd.PreRunE = func(_ *cobra.Command, _ []string) error {
		if token != "-" {
			return nil
		}
		buf, err := readAllStdin()
		if err != nil {
			return fmt.Errorf("read --token from stdin: %w", err)
		}
		token = string(buf)
		return nil
	}
	return cmd
}

