		}
		contextName = defaultContextName(provider, handle, host)
	}
	trimmedIssuer := strings.TrimRight(issuerURL, "/")

	if err := contexts.Modify(configDir, func(f *contexts.File) (bool, error) {
		if existing := f.Find(contextName); existing != nil && existing.Handle != "" && existing.Handle != handle {
			fmt.Fprintf(cmd.ErrOrStderr(), "Replaced context %q (was %s, now %s)\n", contextName, existing.Handle, handle)
